Test.Text:

      create procedure CK.sZoneCreate 
      (
	      @ActorId int,
	      @ZoneIdResult int output
      )
      as
      begin
          if @ActorId <= 0 throw 50000, 'Security.AnonymousNotAllowed', 1;

	      --[beginsp]

	      --<PreZoneCreate revert />

	      -- A Zone is a Group whose ZoneId is 0.  
	      exec CK.sGroupCreate @ActorId, 0, @ZoneIdResult output;

	      -- Do create the Zone
	      insert into CK.tZone( ZoneId ) values ( @ZoneIdResult );

	      --<PostZoneCreate />

	      --[endsp]
      end

Test.Description:
-- SetupConfig: {}
create transformer on CK.sZoneCreate
as
begin
  add parameter @ParentZoneId int = 0 before @ZoneIdResult;

  inject "-- stuff..." into "PreZoneCreate";

  in single statement {exec CK.sGroupCreate}
  begin
    replace first {0} with "@ParentZoneId";
  end

  in single part {insert into CK.tZone}
  begin
    add column HierarchicalId = @NewZoneHId;
  end
end

